begin;
create temporary table cal_test(a uuid,b uuid,c uuid,g uuid,other_g uuid,e uuid);
insert into cal_test(a,b,c,g,other_g) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id) select a from cal_test union all select b from cal_test union all select c from cal_test;
insert into public.mb_groups(id,name,owner_id) select g,'Calendar test',a from cal_test union all select other_g,'Hidden group',a from cal_test;
insert into public.mb_members(group_id,user_id) select g,a from cal_test union all select g,b from cal_test union all select other_g,a from cal_test;
insert into public.mb_polls(group_id,title,dates,start_min,end_min,duration_min,activities,deadline,status,final_slot,final_activity) select other_g,'OTHER GROUP SECRET',array['2099-01-03'::date],540,660,60,array['walk'],'2099-01-02T09:00+09:00','finalized','2099-01-03|540','walk' from cal_test;
grant all on cal_test to authenticated;
set local role authenticated;
do $$
declare t record;r jsonb;req jsonb;denied boolean;
begin
 select * into t from cal_test;perform set_config('request.jwt.claim.sub',t.a::text,true);
 req:=jsonb_build_object('user_id',t.a,'from','2099-01-01T00:00+09:00','to','2099-02-01T00:00+09:00');
 r:=public.moyeobom_calendar('save',jsonb_build_object('title','PRIVATE SECRET','starts_at','2099-01-03T09:00+09:00','ends_at','2099-01-03T10:00+09:00','user_id',t.b));
 update cal_test set e=(r->>'id')::uuid;select * into t from cal_test;
 r:=public.moyeobom_calendar('list',req);
 if r::text not like '%PRIVATE SECRET%' or r::text not like '%OTHER GROUP SECRET%' then raise exception 'owner visibility failed';end if;
 perform set_config('request.jwt.claim.sub',t.b::text,true);
 r:=public.moyeobom_calendar('list',req);
 if jsonb_array_length(r)<>2 or r::text like '%SECRET%' or r::text like '%true%' then raise exception 'private title/editable leaked';end if;
 denied:=false;begin perform public.moyeobom_calendar('delete',jsonb_build_object('id',t.e));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'peer delete allowed';end if;
 denied:=false;begin perform public.moyeobom_calendar('save',jsonb_build_object('id',t.e,'title','hacked'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'peer update allowed';end if;
 denied:=false;begin perform count(*) from public.mb_calendar_events;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'direct access allowed';end if;
 perform set_config('request.jwt.claim.sub',t.c::text,true);
 denied:=false;begin perform public.moyeobom_calendar('list',req);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'stranger access allowed';end if;
 perform set_config('request.jwt.claim.sub',t.a::text,true);
 perform public.moyeobom_calendar('save',jsonb_build_object('id',t.e,'title','PUBLIC NAME','starts_at','2099-01-03T09:00+09:00','ends_at','2099-01-03T10:00+09:00','visibility','public'));
 perform set_config('request.jwt.claim.sub',t.b::text,true);r:=public.moyeobom_calendar('list',req);
 if r::text not like '%PUBLIC NAME%' or r::text like '%OTHER GROUP SECRET%' then raise exception 'public/private projection failed';end if;
 perform set_config('request.jwt.claim.sub',t.a::text,true);
 perform public.moyeobom_calendar('delete',jsonb_build_object('id',t.e));r:=public.moyeobom_calendar('list',req);
 if jsonb_array_length(r)<>1 then raise exception 'delete failed';end if;
 denied:=false;begin perform public.moyeobom_calendar('save','{"title":"bad","starts_at":"2099-01-03T10:00+09:00","ends_at":"2099-01-03T09:00+09:00"}');exception when raise_exception then denied:=true;end;if not denied then raise exception 'invalid interval allowed';end if;
end $$;
reset role;
set local role anon;
do $$ declare denied boolean:=false;begin begin perform public.moyeobom_calendar('list','{}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'anon access allowed';end if;end $$;
reset role;
select 'PASS calendar CRUD, owner spoof protection, private redaction, public sharing, other-group redaction, outsider/anon/direct access denial' as result;
rollback;
